/**
 * A área do retângulo — porte de `componentes/viz/piso.js`.
 *
 * "Comprimento × largura" vira uma fórmula decorada quando ninguém mostra o que
 * ela conta. Aqui cada azulejo é 1 m², e a área é literalmente o NÚMERO DE
 * AZULEJOS — dá para contar com o dedo. A multiplicação aparece como o atalho
 * que ela é: quantas fileiras, vezes quantos por fileira.
 *
 * **A cena virou 2D.** No legado era um piso 3D visto de cima, e a perspectiva
 * só atrapalha quem está contando: os azulejos do fundo ficam menores que os da
 * frente. De cima e sem perspectiva, todos têm o mesmo tamanho, que é o ponto.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const MAX = 8;

const piso: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const comprimento = limitar(Math.round(numeroDe(valores, 'c', 1)), 1, MAX);
    const largura = limitar(Math.round(numeroDe(valores, 'l', 1)), 1, MAX);
    const area = comprimento * largura;
    const alvo = numeroDe(info, 'alvo', 12);
    const ok = info.ok === true;

    titulo(ctx, L, A, `Área: ${area} m²`);

    // O lado do azulejo é o mesmo nos dois eixos — senão a contagem mente.
    const disponivelL = L * 0.62;
    const disponivelA = A * 0.5;
    const lado = Math.min(disponivelL / MAX, disponivelA / MAX);

    const totalL = comprimento * lado;
    const totalA = largura * lado;
    const x0 = L * 0.46 - totalL / 2;
    const y0 = A * 0.52 - totalA / 2;

    // O contrapiso, para a grade não flutuar.
    retangulo(
      ctx,
      x0 - lado * 0.3,
      y0 - lado * 0.3,
      totalL + lado * 0.6,
      totalA + lado * 0.6,
      4,
      cor.palha,
      cor.trilho,
      1,
    );

    // Os azulejos, em xadrez de dois tons — é o xadrez que deixa contar.
    const pulso = ok ? 0.5 + 0.5 * Math.sin(t * 3) : 0;
    for (let i = 0; i < comprimento; i++) {
      for (let j = 0; j < largura; j++) {
        const claro = (i + j) % 2 === 0;
        const preenchimento = ok ? (claro ? '#e9b949' : '#d8a838') : claro ? '#4aa3e0' : '#3d8fce';

        retangulo(
          ctx,
          x0 + i * lado + 1,
          y0 + j * lado + 1,
          lado - 2,
          lado - 2,
          3,
          preenchimento,
          cor.contraste,
          1,
        );
      }
    }

    if (ok) {
      ctx.strokeStyle = cor.ouro;
      ctx.globalAlpha = 0.35 + pulso * 0.4;
      ctx.lineWidth = 3;
      ctx.strokeRect(x0 - 2, y0 - 2, totalL + 4, totalA + 4);
      ctx.globalAlpha = 1;
    }

    // As cotas: é delas que sai a conta.
    const miudo = limitar(A * 0.04, 9, 13);
    const tinta = ok ? cor.ouro : cor.texto;

    texto(ctx, `comprimento = ${comprimento} m`, x0 + totalL / 2, y0 - miudo * 1.6, miudo, {
      cor: tinta,
      peso: 700,
    });

    ctx.save();
    ctx.translate(x0 - miudo * 1.4, y0 + totalA / 2);
    ctx.rotate(-Math.PI / 2);
    texto(ctx, `largura = ${largura} m`, 0, 0, miudo, { cor: tinta, peso: 700 });
    ctx.restore();

    texto(
      ctx,
      `${comprimento} × ${largura} = ${area}`,
      L * 0.46,
      y0 + totalA + miudo * 2,
      miudo * 1.15,
      { cor: tinta, peso: 800 },
    );

    rodape(ctx, L, A, ok, 'Cobre a meta exatamente ✔', `Meta: ${alvo} m².`);
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default piso;
